const _TW_C  = "僞偽啓啟喫吃嫺嫻嬀媯峯峰幺么擡抬棱稜檐簷污汙泄洩潙溈潨潀爲為牀床痹痺癡痴皁皂着著睾睪祕秘竈灶糉粽繮韁纔才羣群脣唇蔘參蔿蒍衆眾裏裡覈核踊踴鉢缽鍼針鮎鯰麪麵齶顎";

let _twT = null;
function twTables(){
  if (_twT) return _twT;
  const chars = s => { const m = new Map(), a = Array.from(s);
    for (let i = 0; i < a.length; i += 2) m.set(a[i], a[i+1]); return m; };
  const phr = s => {
    const m = new Map(), first = new Set(); let max = 0;
    for (const line of s.split('\n')){
      const i = line.indexOf('\t'); if (i < 1) continue;
      const k = line.slice(0, i), a = Array.from(k);
      m.set(k, line.slice(i + 1)); first.add(a[0]);
      if (a.length > max) max = a.length;
    }
    return { m, first, max };
  };
  const p = phr(_S2T_P), w = phr(_TW_P);
  _twT = { cmap: chars(_S2T_C), wcmap: chars(_TW_PC), vmap: chars(_TW_C),
           pmap: p.m, pfirst: p.first, pmax: p.max,
           wmap: w.m, wfirst: w.first, wmax: w.max };
  return _twT;
}

/** 一輪「最長詞優先」的取代；cmap 有給的話，沒中詞的字再做逐字轉換 */
function _twPass(cps, pmap, pfirst, pmax, cmap){
  let out = '';
  for (let i = 0; i < cps.length; ){
    const ch = cps[i];
    if (pfirst.has(ch)){
      const max = Math.min(pmax, cps.length - i);
      let hit = null, hl = 0;
      for (let L = max; L >= 2; L--){
        const v = pmap.get(cps.slice(i, i + L).join(''));
        if (v !== undefined){ hit = v; hl = L; break; }
      }
      if (hit !== null){ out += hit; i += hl; continue; }
    }
    out += (cmap && cmap.get(ch)) || ch;
    i++;
  }
  return out;
}

/** 簡體（或混英文）→ 台灣正體。非漢字原封不動，英文完全不碰。 */
function toTW(text){
  if (!text) return text;
  const s0 = String(text);
  // 沒有漢字就不用忙。\uD840-\uD87F 是擴充區漢字（𫚭 這種）的前導碼元。
  if (!/[\u3400-\u9FFF\uF900-\uFAFF\uD840-\uD87F]/.test(s0)) return s0;
  const t = twTables();
  let s = _twPass(Array.from(s0), t.pmap, t.pfirst, t.pmax, t.cmap);      // STPhrases + STCharacters
  s = _twPass(Array.from(s), t.wmap, t.wfirst, t.wmax, t.wcmap);          // TWPhrases（台灣用語）
  return Array.from(s).map(c => t.vmap.get(c) || c).join('');             // TWVariants（台灣字形）
}
